  "technique": [
    {
      "tip": "Trail Brake Aggressively",
      "detail": "Implement full trail-braking (78% of zones) in the braking zones leading into Paddock Hill and Hawthorn to transfer weight smoothly and maintain rotation."
    },
    {
      "tip": "Counter-Steer Correction",
