    },
    {
      "tip": "Throttle Modulation",
      "detail": "Eliminate binary throttle driving; use smooth, progressive throttle application on exit from Druids and Graham Hill Bend to maximize acceleration without inducing wheel spin."
    },
    {
      "tip": "Kerb Management",
      "detail": "Avoid hard kerb strikes entirely; this mechanical noise destabilizes the car and costs time. Focus on utilizing track limits rather than aggressively hitting kerbs."
    }
  ]
}

